import os
import torch


class Config:
    # --- System Configuration ---
    SEED = 42
    NUM_WORKERS = 12
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # --- Path Configuration ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata Paths (Generated by the provided script)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory (Specific to Idea 7)
    WORKING_DIR = "./working/idea_7"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Configuration ---
    # "Augment-then-Crop" Strategy
    # Load at 96x96 (original) -> Augment -> Center Crop to 64x64
    # This preserves the 32x32 ROI + 16px context buffer while removing edge artifacts
    RAW_IMAGE_SIZE = 96
    CROP_SIZE = 64

    # Normalization Constants (ImageNet Defaults for Pretrained Models)
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # --- Model Configuration ---
    # Heterogeneous Ensemble: ConvNeXt-Tiny + EfficientNetV2-Small
    # We train 5 folds for EACH architecture (10 total models)
    MODEL_ARCHS = ["convnext_tiny", "tf_efficientnetv2_s"]

    # Exponential Moving Average for weights
    USE_EMA = True
    EMA_DECAY = 0.9999

    # --- Training Configuration ---
    N_FOLDS = 5
    EPOCHS = 25
    BATCH_SIZE = 256  # Optimized for A100 40GB and small image size

    # Optimization
    LEARNING_RATE = 2e-4
    WEIGHT_DECAY = 0.05

    # Regularization
    MIXUP_ALPHA = 0.2

    # --- Inference Configuration ---
    # Test Time Augmentation: 8 views (Dihedral group D4)
    TTA_VIEWS = 8

    # --- Debugging ---
    # Toggle to True to run on a small subset (e.g., 1000 samples) for pipeline checks
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 1000

    @classmethod
    def setup(cls):
        """
        Creates the necessary directory structure for caching, checkpoints, and submissions.
        """
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
